<?php
declare(strict_types=1);
if(empty($wams['authorized'])){http_response_code(403);exit;}$cfg=$wams['config'];function x(mixed$v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}$rows=[];$header=[];$error='';$bytes=0;
try{$url=(string)($cfg['remoteUrl']??'');if(!filter_var($url,FILTER_VALIDATE_URL))throw new RuntimeException('CSV-URL ist ungültig.');$ctx=stream_context_create(['http'=>['timeout'=>max(2,min(60,(int)($cfg['timeoutSeconds']??20))),'ignore_errors'=>true,'header'=>"Accept: text/csv,text/plain\r\nUser-Agent: WAMS-CSV/3.0\r\n"]]);$raw=@file_get_contents($url,false,$ctx);if($raw===false)throw new RuntimeException('CSV-Quelle nicht erreichbar.');$bytes=strlen($raw);$d=($cfg['delimiter']??',')==='\t'?"\t":($cfg['delimiter']??',');$f=fopen('php://temp','r+');fwrite($f,$raw);rewind($f);while(($r=fgetcsv($f,0,$d))!==false)$rows[]=array_map(fn($v)=>trim((string)$v),$r);fclose($f);if(($cfg['hasHeader']??true)&&$rows)$header=array_shift($rows);$w=0;foreach($rows as$r)$w=max($w,count($r));if(!$header)for($i=0;$i<$w;$i++)$header[]='Spalte '.($i+1);foreach($rows as&$r)$r=array_pad($r,count($header),'');unset($r);$show=$cfg['showColumns']??[];if($show){$ix=[];foreach($show as$n){$i=array_search($n,$header,true);if($i!==false)$ix[]=$i;}if($ix){$header=array_map(fn($i)=>$header[$i],$ix);$rows=array_map(fn($r)=>array_map(fn($i)=>$r[$i],$ix),$rows);}}}catch(Throwable$e){$error=$e->getMessage();}$ren=$cfg['columnRenames']??[];$links=$cfg['columnLinks']??[];$shown=array_map(fn($h)=>$ren[$h]??$h,$header);$refresh=max(0,(int)($cfg['refreshSeconds']??0));
?><!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=x($cfg['title']??'CSV Reporting')?></title><?php if($refresh):?><meta http-equiv="refresh" content="<?=$refresh?>"><?php endif?><link rel="stylesheet" href="<?=x($wams['styleUrl'])?>"></head><body><main class="cr"><header><div><h1><?=x($cfg['heading']??'CSV Reporting')?></h1><p><?=count($rows)?> Zeilen · <?=number_format($bytes/1024,1,',','.')?> KiB</p></div><?php if($wams['canManage']):?><a href="<?=x($wams['manageUrl'])?>">Editor</a><?php endif?></header><?php if($error):?><div class="err"><?=x($error)?></div><?php else:?><section><div class="tools"><input id="search" type="search" placeholder="Suchen"><select id="size"><option>25</option><option selected>50</option><option>100</option><option>250</option></select><button id="reset">Zurücksetzen</button><span id="count"></span></div><div class="filters"><?php foreach($shown as$i=>$h):?><label><?=x($h)?><input data-col="<?=$i?>" type="search"></label><?php endforeach?></div><div class="scroll"><table id="data"><thead><tr><?php foreach($shown as$i=>$h):?><th data-sort="<?=$i?>"><?=x($h)?> ↕</th><?php endforeach?></tr></thead><tbody><?php foreach($rows as$r):?><tr><?php foreach($r as$i=>$v):?><td><?php $key=$header[$i]??'';if(isset($links[$key])):$href=str_replace('{value}',rawurlencode($v),$links[$key]);?><a href="<?=x($href)?>" target="_blank" rel="noopener"><?=x($v)?></a><?php else:?><?=x($v)?><?php endif?></td><?php endforeach?></tr><?php endforeach?></tbody></table></div><footer><button id="prev">Zurück</button><span id="page"></span><button id="next">Weiter</button></footer></section><?php endif?></main><script src="<?=x($wams['scriptUrl'])?>"></script></body></html>
